import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';
import { statement } from '../src/statements.js';

test('statement returns invoices issued to a customer', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  const r = statement('C-001', [issued1.value, issued2.value], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.invoices.length, 2);
  assert.equal(r.value.invoices[0].number, 'INV-2026-0001');
  assert.equal(r.value.invoices[1].number, 'INV-2026-0002');
});

test('statement rejects unknown customer', () => {
  const r = statement('C-999', [], '2026-10-31');
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('statement excludes draft invoices', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued2 = issueInvoice(invoice2.value, []);
  const r = statement('C-001', [invoice1.value, issued2.value], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
  assert.equal(r.value.invoices[0].number, 'INV-2026-0001');
});

test('statement excludes future-dated invoices', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-11-15',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  const r = statement('C-001', [issued1.value, issued2.value], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
  assert.equal(r.value.invoices[0].issueDate, '2026-10-07');
});

test('statement includes paid invoices with zero due', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.value.total, date: '2026-10-10' });
  const r = statement('C-002', [paid.value], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
  assert.equal(r.value.invoices[0].due, 0);
});

test('statement excludes paid invoices from totalDue', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.value.total, date: '2026-10-10' });
  const r = statement('C-002', [paid.value], '2026-10-31');
  assert.equal(r.value.totalDue, 0);
});

test('statement calculates correct due amounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const totals = invoiceTotals(issued.value);
  const r = statement('C-001', [issued.value], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].total, totals.value.total);
  assert.equal(r.value.invoices[0].due, totals.value.total);
});

test('statement shows partial payments', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const totals = invoiceTotals(issued.value);
  const payment1 = recordPayment(issued.value, { amount: 30, date: '2026-10-10' });
  const r = statement('C-001', [payment1.value], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].due, totals.value.total - 30);
});

test('statement sorts invoices by issueDate', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-20',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  const invoice3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued3 = issueInvoice(invoice3.value, ['INV-2026-0001', 'INV-2026-0002']);
  const r = statement('C-001', [issued1.value, issued2.value, issued3.value], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 3);
  assert.equal(r.value.invoices[0].issueDate, '2026-10-05');
  assert.equal(r.value.invoices[1].issueDate, '2026-10-15');
  assert.equal(r.value.invoices[2].issueDate, '2026-10-20');
});

test('statement calculates totalDue correctly', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const totals1 = invoiceTotals(issued1.value);

  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'STICKER', qty: 3 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  const totals2 = invoiceTotals(issued2.value);

  const r = statement('C-001', [issued1.value, issued2.value], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.totalDue, totals1.value.total + totals2.value.total);
});

test('statement with empty invoices array', () => {
  const r = statement('C-001', [], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 0);
  assert.equal(r.value.totalDue, 0);
});

test('statement with null invoices array', () => {
  const r = statement('C-001', null, '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 0);
  assert.equal(r.value.totalDue, 0);
});

test('statement filters by customerId', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const invoice2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued2 = issueInvoice(invoice2.value, []);
  const r = statement('C-001', [issued1.value, issued2.value], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
  assert.equal(r.value.invoices[0].number, 'INV-2026-0001');
});

test('statement includes invoice metadata', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const r = statement('C-001', [issued.value], '2026-10-31');
  assert.equal(r.ok, true);
  const inv = r.value.invoices[0];
  assert.ok('number' in inv);
  assert.ok('issueDate' in inv);
  assert.ok('dueDate' in inv);
  assert.ok('total' in inv);
  assert.ok('due' in inv);
  assert.equal(inv.dueDate, '2026-10-21');
});

test('statement with multiple partial payments', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const totals = invoiceTotals(issued.value);
  const paid1 = recordPayment(issued.value, { amount: 20, date: '2026-10-10' });
  const paid2 = recordPayment(paid1.value, { amount: 30, date: '2026-10-15' });
  const r = statement('C-001', [paid2.value], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].due, totals.value.total - 50);
  assert.equal(r.value.totalDue, totals.value.total - 50);
});

test('statement correctly maps customer by normalized ID', () => {
  const invoice = createInvoice({
    customerId: 'c-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const r = statement('C-001', [issued.value], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.invoices.length, 1);
});

test('statement on exact asOf date includes invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const r = statement('C-001', [issued.value], '2026-10-07');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
});

test('statement one day before asOf excludes invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const r = statement('C-001', [issued.value], '2026-10-06');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 0);
});

test('statement includes partially_paid invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const partial = recordPayment(issued.value, { amount: 30, date: '2026-10-10' });
  const r = statement('C-001', [partial.value], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
  assert.ok(r.value.invoices[0].due > 0);
});

test('statement with mixed invoice statuses', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const totals2 = invoiceTotals(invoice2.value);
  const issued2 = issueInvoice(invoice2.value, []);
  const paid2 = recordPayment(issued2.value, { amount: totals2.value.total, date: '2026-10-10' });

  const r = statement('C-001', [issued1.value, paid2.value], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 2);
  assert.equal(r.value.invoices[0].due, 0);
  assert.ok(r.value.invoices[1].due > 0);
});

test('statement with invoices from different customers', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued1 = issueInvoice(inv1.value, []);
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued2 = issueInvoice(inv2.value, []);
  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'STICKER', qty: 3 }],
  });
  const issued3 = issueInvoice(inv3.value, ['INV-2026-0001', 'INV-2026-0002']);

  const r = statement('C-001', [issued1.value, issued2.value, issued3.value], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 2);
  assert.equal(r.value.invoices[0].number, 'INV-2026-0001');
  assert.equal(r.value.invoices[1].number, 'INV-2026-0003');
});

