import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';
import { statement } from '../src/statements.js';

test('statement returns invoices issued to a customer', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  const r = statement('C-001', [issued1.value, issued2.value], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.invoices.length, 2);
  assert.equal(r.value.invoices[0].number, 'INV-2026-0001');
  assert.equal(r.value.invoices[1].number, 'INV-2026-0002');
});

test('statement rejects unknown customer', () => {
  const r = statement('C-999', [], '2026-10-31');
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('statement excludes draft invoices', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued2 = issueInvoice(invoice2.value, []);
  const r = statement('C-001', [invoice1.value, issued2.value], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
  assert.equal(r.value.invoices[0].number, 'INV-2026-0001');
});

test('statement excludes future-dated invoices', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-11-15',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  const r = statement('C-001', [issued1.value, issued2.value], '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
  assert.equal(r.value.invoices[0].issueDate, '2026-10-07');
});

test('statement includes paid invoices with zero due', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
